WITH matched_keys AS (SELECT dept_name, location FROM departments EXCEPT ALL SELECT dept_name, location FROM departments WHERE budget BETWEEN 1806000 AND 2370000), reconciled AS (SELECT s.* FROM departments s JOIN matched_keys k ON s.dept_name = k.dept_name AND s.location = k.location) SELECT location, STDDEV_SAMP(budget) AS budget_stddev, SORT_ARRAY(COLLECT_SET(location)) AS location_list, ROUND(SUM(budget) / NULLIF(COUNT(CASE WHEN dept_name = 'Marketing' THEN 1 END), 0), 2) AS budget_per_marketing FROM reconciled GROUP BY location
